WITH cleaned AS (SELECT *, LAST_DAY(delivered_date) AS delivered_date_month_end FROM shipments WHERE carrier IS NOT NULL AND YEAR(delivered_date) >= 2025) SELECT dim.channel, dim.status AS order_status, s.status AS shipment_status, COUNT(*) AS num_rows, MIN(s.cost) AS min_cost FROM cleaned s LEFT JOIN orders dim ON s.order_id = dim.id GROUP BY dim.channel, dim.status, s.status ORDER BY shipment_status;
